if (window.top !== window) return;
const stateKey = Symbol.for('openmedia.following-only');
const state = window[stateKey] || (window[stateKey] = { on: false, installed: false, check: null });
const attempts = 'openmedia.following-only.attempts';
const atHome = () => location.pathname === '/';
const onFollowing = () => new URLSearchParams(location.search).get('variant') === 'following';
const allowed = () => {
  const now = Date.now();
  let times = [];
  try { times = JSON.parse(sessionStorage.getItem(attempts) || '[]').filter((at) => now - at < 5000); } catch (_) {}
  if (times.length >= 3) return false;
  times.push(now);
  try { sessionStorage.setItem(attempts, JSON.stringify(times)); } catch (_) {}
  return true;
};
state.on = true;
state.check = () => {
  if (state.on && atHome() && !onFollowing() && allowed()) location.replace('/?variant=following');
};
(window[Symbol.for('openmedia.cleanup')] ||= []).push(() => { state.on = false; });
if (!state.installed) {
  state.installed = true;
  for (const name of ['pushState', 'replaceState']) {
    const original = history[name];
    history[name] = function () {
      const result = original.apply(this, arguments);
      state.check();
      return result;
    };
  }
  window.addEventListener('popstate', () => state.check());
}
state.check();
